import os

import boto3


class SafetyClient:
    def __init__(self):
        self.client = boto3.client('comprehend')

    def detect_toxic_content(self, text):
        response = self.client.detect_toxic_content(
            Text=text,
            LanguageCode='en'
        )
        return response

    def get_configuration(self):
        config = {
            'api_key': os.getenv('AMAZON_COMPREHEND_API_KEY'),
            'region': os.getenv('AMAZON_COMPREHEND_REGION', 'us-west-2')
        }
        return config

if __name__ == '__main__':
    client = SafetyClient()
    print(client.get_configuration())

import boto3

def apply_thresholds(text, thresholds):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    sentiment_score = response['SentimentScore']

    decision = {}
    for category, threshold in thresholds.items():
        if category in sentiment_score:
            decision[category] = sentiment_score[category] >= threshold
        else:
            decision[category] = False
    return decision

if __name__ == '__main__':
    sample_text = 'I love this product! It is the best thing ever.'
    sample_thresholds = {'Positive': 0.5, 'Negative': 0.5}
    decision = apply_thresholds(sample_text, sample_thresholds)
    print(decision)

import requests

API_URL = 'https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze'
API_KEY = 'YOUR_API_KEY_HERE'

def moderate_batch(messages):
    headers = {
        'Content-Type': 'application/json',
    }
    data = {
        'comment': {'text': messages},
        'languages': ['en'],
        'requestedAttributes': {'TOXICITY': {}},
    }
    response = requests.post(API_URL, json=data, headers=headers, params={'key': API_KEY})
    result = response.json()
    return result['attributeScores']['TOXICITY']['summaryScore']['value']

if __name__ == '__main__':
    messages = ['This is a nice message.', 'This is a toxic message.']
    decisions = [moderate_batch(message) for message in messages]
    print(decisions)
